+/** Original, quiet Web Audio tones. No samples, microphone or external assets. */
+class GhostAudio {
+  constructor({createContext = () => new (window.AudioContext || window.webkitAudioContext)(), setTimer = setTimeout, clearTimer = clearTimeout} = {}) {
+    this.createContext = createContext; this.setTimer = setTimer; this.clearTimer = clearTimer;
