+    this.band = null; this.suppressedGeneration = null;
+  }
+  async setEnabled(enabled) {
+    this.enabled = enabled;
+    if (!enabled) { this.stop(true); return; }
+    await this.unlock();
+  }
+  async unlock() {
+    if (!this.enabled) return;
+    if (!this.context || this.context.state === "closed") {
+      this.context = this.createContext();
+      this.master = this.context.createGain();
+      this.master.gain.value = 0.035;
+      this.master.connect(this.context.destination);
+    }
+    const context = this.context;
+    if (context.state === "suspended") await context.resume();
+    if (this.enabled && this.context === context) this.schedule();
+  }
+  clearTimers() {
+    if (this.timer !== null) this.clearTimer(this.timer);
+    if (this.endTimer !== null) this.clearTimer(this.endTimer);
+    this.timer = this.endTimer = null;
+  }
+  stop(close = false) {
+    this.clearTimers(); this.band = null;
+    for (const node of this.nodes) {
+      try { node.osc.stop(); } catch (_) { /* already ended */ }
+      node.osc.disconnect(); node.gain.disconnect();
+    }
+    this.nodes.clear();
+    if (close && this.context) {
+      this.master?.disconnect();
+      this.context.close().catch(() => {});
+      this.context = this.master = null;
+    }
+  }
+  reset() {
+    this.suppressedGeneration = this.frame?.generation;
+    this.stop(false);
